UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Magnesium Maintenance","body":"**After loading dose, start maintenance infusion:** [1,5]\n\n**Standard protocol:**\n- **1-2 g/hour IV continuous infusion**\n- Typical: 40g MgSO4 in 1000mL NS at 50mL/hr (2g/hr)\n- Continue for 24-48 hours postpartum (or after last seizure)\n\n**Therapeutic levels:**\n- Target: 4.8-8.4 mg/dL (4-7 mEq/L)\n- Seizure prophylaxis effective at 4.8-8.4 mg/dL\n\n**Monitoring:**\n- Reflexes (patellar) every 1-2 hours\n- Respiratory rate every hour\n- Urine output (Foley catheter)\n- Magnesium level q6h or if toxicity suspected\n\n**Renal adjustment:**\n- CrCl <30: reduce to 1g/hour\n- Anuria: hold maintenance, check levels frequently\n\n**Watch for toxicity:**\n- Absent patellar reflexes, respiratory depression or cardiovascular instability require immediate assessment and stopping magnesium. Do not wait for a serum level.\n- See the [Magnesium Toxicity table and rescue treatment](#/node/eclampsia-mag-toxicity) for the ACOG reference concentrations. [1]","citation":[1,5],"next":"eclampsia-mag-toxicity","summary":"Magnesium 1-2g/hr continuous — check reflexes q1-2h, RR hourly, UOP >25mL/hr"}'::jsonb
