UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Magnesium Toxicity","body":"**Recognize and treat magnesium toxicity immediately.** [1,5]\n\n**Serum magnesium and toxicity: ACOG reference concentrations** [1]\n| Serum magnesium (mg/dL) | Associated finding |\n|-----------|------------------|\n| >9 | Loss of patellar reflexes |\n| >12 | Respiratory paralysis |\n| >30 | Cardiac arrest |\n\nThese are approximate associations from ACOG Practice Bulletin 222, Table 2, not guaranteed onset thresholds or safe levels below each cutoff. Toxicity can occur at lower concentrations. **Stop magnesium and treat suspected toxicity based on clinical findings; do not wait for a magnesium result or for the cardiac-arrest concentration.** [1]\n\n**Management of toxicity:**\n\n**1. Stop magnesium infusion immediately**\n\n**2. Calcium gluconate (antidote):**\n- **1g (10mL of 10% solution) IV over 3-5 minutes**\n- Can repeat in 5 minutes if needed\n- Works within 1-3 minutes\n\n**3. Supportive care:**\n- Ventilatory support (BVM, intubation)\n- Continuous cardiac monitoring\n- IV fluids for diuresis (if renal function adequate)\n\n**Prevention:**\n- Check reflexes before each bolus\n- Never give mag if reflexes absent\n- Ensure UOP >25mL/hr\n- Respiratory rate >12/min","citation":[1,5],"next":"eclampsia-refractory","treatment":{"firstLine":{"drug":"Calcium Gluconate","dose":"1g (10mL of 10% solution)","route":"IV","frequency":"Over 3-5 minutes","duration":"May repeat in 5 minutes if needed","notes":"Antidote for magnesium toxicity. Give immediately if respiratory depression or absent reflexes."},"monitoring":"Continuous cardiac monitoring. Monitor respiratory status and mental status. Check magnesium level after administration."},"summary":"Absent reflexes or respiratory depression: stop magnesium and treat without waiting for a level; calcium gluconate 1g IV is the antidote","safetyLevel":"critical"}'::jsonb
WHERE id = 'eclampsia-mag-toxicity' AND tree_id = 'eclampsia';

